package com.example

/**
 * 10 ශ්‍රේණිය ඉතිහාසය - කාණ්ඩ 11 සිට 16 දක්වා (120 unique cards).
 * 100% curriculum-aligned with official Sri Lankan O/L Grade 10 History Syllabus.
 */
object FlashcardBankHistoryGrade10SetsPart2 {

  fun getCard(setNum: Int, cardNum: Int): CardContentTuple? {
    val c = cardNum.coerceIn(1, 20)
    return when (setNum) {
      11 -> set11VijayabahuLiberation[(c - 1) % 20]
      12 -> set12ParakramabahuTheGreat[(c - 1) % 20]
      13 -> set13Nissankamalla[(c - 1) % 20]
      14 -> set14AgricultureAndTanks[(c - 1) % 20]
      15 -> set15AnuradhapuraPolonnaruwaArt[(c - 1) % 20]
      16 -> set16DambadeniyaYapahuwa[(c - 1) % 20]
      else -> null
    }
  }

